import { http } from '@/shared/api/httpClient';
import type { CommentItem, Page } from '@/shared/api/types';

export function fetchComments(titleId: number, cursor?: string): Promise<Page<CommentItem>> {
  return http.get<Page<CommentItem>>(`/titles/${titleId}/comments`, { query: { cursor } });
}

export function postComment(
  titleId: number,
  body: string,
  parentId: number | null,
): Promise<CommentItem> {
  return http.post<CommentItem>(`/titles/${titleId}/comments`, { body, parentId });
}

export function deleteComment(id: number): Promise<void> {
  return http.del(`/comments/${id}`);
}
